sys_ws_operation.operation_script:
(function process(request, response) {
    try {
        var body = request.body.data;

        var gr = new GlideRecord('x_1955226_connecto_connection');
        gr.query();

        if (gr.next()) {
            // update existing
            gr.base_url = body.baseUrl;
            gr.client_id = body.clientId;
            gr.client_secret = body.clientSecret;

            gr.update();

            response.setStatus(200);
            response.setBody({
                success: true,
                sys_id: gr.getUniqueValue(),
                updated: true
            });
        } else {
            // create new
            gr.initialize();
            gr.base_url = body.baseUrl;
            gr.client_id = body.clientId;
            gr.client_secret = body.clientSecret;

            var sysId = gr.insert();

            response.setStatus(201);
            response.setBody({
                success: true,
                sys_id: sysId,
                created: true
            });
        }

    } catch (error) {
        response.setStatus(500);
        response.setBody({
            success: false,
            message: error.message
        });
    }
})(request, response);
